ZM, TM, BASE, XDEF = [1, 2, 4, 8], [1, 1.5, 2, 3, 4], 400, 500
def chest_xp(dl):
    mz = re.match(r"Zone(\d)_.+_Tier(\d+)$", dl)
    if mz and 1 <= int(mz.group(1)) <= 4 and 1 <= int(mz.group(2)) <= 5:
        return int(round(BASE * ZM[int(mz.group(1)) - 1] * TM[int(mz.group(2)) - 1]))
    return XDEF
