# ---- ExpCfg hooks for the kit (compiled after emit: they read the kit's current values through CfgFn.cmdGet)
M(cfg, r"""
public static boolean idOk(String id, int max) {
  if (id == null || id.length() == 0 || id.length() > max) return false;
  for (int j = 0; j < id.length(); j++) {
    char c = id.charAt(j);
    if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_')) return false;
  }
  return true;
}""")
# the kit's current value of a whole-number row (the file as the kit holds it, pending in-game changes included), else def
M(cfg, r"""
public static long kitLong(String key, long def) {
  try {
    String v = @PKG@.CfgFn.cmdGet(key);
    if (v == null) return def;
    return Long.parseLong(v.trim());
  } catch (Throwable t) { return def; }
}""")
# the kit's current value of a bool row (what an admin just set, even before the save + reload ~0.5 s later puts it in the field)
M(cfg, r"""
public static boolean kitBool(String key, boolean def) {
  try {
    String v = @PKG@.CfgFn.cmdGet(key);
    if ("true".equals(v)) return true;
    if ("false".equals(v)) return false;
  } catch (Throwable t) { }
  return def;
}""")
# the dlist() rule of apply(): exactly n numbers (empty items dropped), each 0..1000 - refused here instead of "default used" there
M(cfg, r"""
public static String multErr(String v, int n, String what) {
  String[] xs = split(v);
  if (xs.length != n) return "Needs " + n + " numbers from 0 to 1000 (" + what + "), comma separated - got " + xs.length + ".";
  for (int i = 0; i < xs.length; i++) {
    double d = -1.0;
    try { d = Double.parseDouble(xs[i]); } catch (Throwable t) { return "'" + xs[i] + "' is not a number (" + n + " numbers from 0 to 1000, comma separated)."; }
    if (Double.isNaN(d) || d < 0.0 || d > 1000.0) return "'" + xs[i] + "' is outside 0 to 1000.";
  }
  return null;
}""")
# empty = no sound; otherwise the id must be a sound event of the game assets (sound() would warn and play nothing). An asset map that
# cannot be asked (bare JVM) accepts the id
M(cfg, r"""
public static String soundErr(String v) {
  if (v == null || v.length() == 0) return null;
  int idx = Integer.MIN_VALUE + 1;
  try { idx = @SEV@.getAssetMap().getIndex(v); } catch (Throwable t) { return null; }
  if (idx == Integer.MIN_VALUE) return "The game has no sound event '" + v + "' - use an id like SFX_Discovery_Z1_Short, or empty for no sound.";
  return null;
}""")
M(cfg, r"""
public static String check(String key, String value) {
  if (key == null) return null;
  if (key.startsWith("chest.xp[") || key.startsWith("zone.xp[")) {
    if (value == null) return null;
    int a = key.indexOf('[');
    String id = key.endsWith("]") ? key.substring(a + 1, key.length() - 1) : "";
    if (!idOk(id, 80)) return (key.startsWith("chest") ? "A drop list id" : "A region id") + " is letters, digits and _ only (like Zone1_Tier1), at most 80.";
    return null;
  }
  if (key.startsWith("title[")) {
    if (value == null) return null;
    String tid = key.endsWith("]") ? key.substring(6, key.length() - 1) : "";
    int ti = @PKG@.ExpDefs.title(tid);
    if (ti < 0 || @PKG@.ExpDefs.T_KIND[ti] == 1) return "Not a title with a number. Title ids: " + NUM_TITLES + " (zone titles unlock by regions).";
    return null;
  }
  if (value == null) return null;
  if (key.equals("chests.zoneMult") || key.equals("chunks.zoneMult")) return multErr(value, 4, "zones 1 to 4");
  if (key.equals("chests.tierMult")) return multErr(value, 5, "tiers 1 to 5");
  // 0.2.4 Unclaimed Luggage: four numbers (tiers I-IV / zones 1-4), each 0 to 1000 (dlist's rule)
  if (key.equals("luggage.tierWeights") || key.equals("luggage.bags") || key.equals("luggage.coinsMin") || key.equals("luggage.coinsMax") || key.equals("luggage.xp")) return multErr(value, 4, "tiers I to IV");
  if (key.equals("luggage.coinZoneMult")) return multErr(value, 4, "zones 1 to 4");
  if (key.equals("spots.sound") || key.equals("spots.secretSound") || key.equals("checklist.sound")) return soundErr(value);
  if (key.equals("spots.defaultRadius")) {
    long mx = kitLong("spots.maxRadius", (long) SPOT_RMAX);
    long v = @PKG@.ExpDefs.parseNum(value, -1L);
    if (v > mx) return "?Largest spot radius is " + mx + " blocks, so new spots get " + mx + " until you raise it. Save " + v + " anyway?";
  }
  if (key.equals("spots.maxRadius")) {
    long dr = kitLong("spots.defaultRadius", (long) SPOT_R);
    long v = @PKG@.ExpDefs.parseNum(value, Long.MAX_VALUE);
    if (v < dr) return "?New spot radius is " + dr + " blocks, so new spots get only " + v + " until you lower it. Save " + v + " anyway?";
  }
  return null;
}""")
