# ---- LgSite: one registry line (state 0 out, 1 claimed - shared for shareSeconds, 2 gone - waiting to come back)
for _f in ("int x", "int y", "int z", "int tier", "int lvl", "int state", "long placedAt", "long lootedAt", "long lastNear", "long nonce", "String who"):
    F(lgsite, "public %s;" % _f)
C(lgsite, 'public LgSite() { this.who = ""; }')
M(lgsite, r"""
public String line() {
  return this.x + "\t" + this.y + "\t" + this.z + "\t" + this.tier + "\t" + this.lvl + "\t" + this.state + "\t" + this.placedAt + "\t" + this.lootedAt + "\t" + this.lastNear + "\t" + this.nonce + "\t" + (this.who == null ? "" : this.who);
}""")
M(lgsite, r"""
public static @PKG@.LgSite parse(String line) {
  if (line == null) return null;
  String t = line.trim();
  if (t.length() == 0 || t.startsWith("#")) return null;
  String[] p = line.split("\t", -1);
  if (p.length < 10) return null;
  try {
    @PKG@.LgSite s = new @PKG@.LgSite();
    s.x = Integer.parseInt(p[0].trim()); s.y = Integer.parseInt(p[1].trim()); s.z = Integer.parseInt(p[2].trim());
    s.tier = Integer.parseInt(p[3].trim()); s.lvl = Integer.parseInt(p[4].trim()); s.state = Integer.parseInt(p[5].trim());
    s.placedAt = Long.parseLong(p[6].trim()); s.lootedAt = Long.parseLong(p[7].trim()); s.lastNear = Long.parseLong(p[8].trim());
    s.nonce = Long.parseLong(p[9].trim());
    s.who = p.length > 10 ? p[10].trim() : "";
    if (s.tier < 1 || s.tier > 4 || s.state < 0 || s.state > 2 || s.lvl < 1 || s.y < 0 || s.y >= 320) return null;
    return s;
  } catch (Throwable e) { return null; }
}""")
# the claims "uuid:ms;uuid:ms" - this player's last claim of this spot (0 = never)
M(lgsite, r"""
public long claimedAt(java.util.UUID u) {
  if (u == null || this.who == null || this.who.length() == 0) return 0L;
  String key = u.toString() + ":";
  String[] ps = this.who.split(";");
  long best = 0L;
  for (int i = 0; i < ps.length; i++) {
    if (!ps[i].startsWith(key)) continue;
    try { long v = Long.parseLong(ps[i].substring(key.length())); if (v > best) best = v; } catch (Throwable t) { }
  }
  return best;
}""")
# add a claim, dropping claims older than the cooldown (bounded: at most 64 kept)
M(lgsite, r"""
public void claim(java.util.UUID u, long now, long keepMs) {
  StringBuilder sb = new StringBuilder();
  String[] ps = this.who == null || this.who.length() == 0 ? new String[0] : this.who.split(";");
  int n = 0;
  String key = u.toString() + ":";
  for (int i = ps.length - 1; i >= 0 && n < 63; i--) {
    if (ps[i].length() == 0 || ps[i].startsWith(key)) continue;
    int c = ps[i].lastIndexOf(':');
    long v = 0L;
    try { v = Long.parseLong(ps[i].substring(c + 1)); } catch (Throwable t) { continue; }
    if (now - v > keepMs) continue;
    if (sb.length() > 0) sb.insert(0, ";");
    sb.insert(0, ps[i]);
    n++;
  }
  if (sb.length() > 0) sb.append(";");
  sb.append(key).append(now);
  this.who = sb.toString();
}""")

# ---- LgReg: per world, the sites (loaded on first use from luggage/<wf>.tsv), saved atomically (write-ahead: before a block is placed
# and before loot is given). Every access is on the world's own thread (ExpTick, the Use supplier, the break events, commands).
F(lgreg, "public static java.nio.file.Path DIR;")
F(lgreg, "public static final java.util.concurrent.ConcurrentHashMap W = new java.util.concurrent.ConcurrentHashMap();")
F(lgreg, "public static final java.util.concurrent.ConcurrentHashMap NAMES = new java.util.concurrent.ConcurrentHashMap();")
F(lgreg, "public static final java.util.concurrent.atomic.AtomicLong SAVE_FAILS = new java.util.concurrent.atomic.AtomicLong();")
M(lgreg, r"""
public static java.nio.file.Path file(String wf) {
  return DIR == null ? null : DIR.resolve(wf + ".tsv");
}""")
M(lgreg, "public static synchronized void add(java.util.ArrayList l, @PKG@.LgSite s) { if (l != null && s != null) l.add(s); }")
M(lgreg, "public static synchronized boolean remove(java.util.ArrayList l, @PKG@.LgSite s) { return l != null && l.remove(s); }")
M(lgreg, "public static synchronized Object[] snap(java.util.ArrayList l) { if (l == null) return new Object[0]; return l.toArray(); }")
M(lgreg, r"""
public static java.util.ArrayList sites(String wn) {
  String wf = @PKG@.ChestReg.wf(wn);
  Object o = W.get(wf);
  if (o instanceof java.util.ArrayList) return (java.util.ArrayList) o;
  java.util.ArrayList l = new java.util.ArrayList();
  java.nio.file.Path f = file(wf);
  int bad = 0;
  try {
    if (f != null && java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0])) {
      java.util.List ls = java.nio.file.Files.readAllLines(f, java.nio.charset.StandardCharsets.UTF_8);
      for (int i = 0; i < ls.size(); i++) {
        String ln = (String) ls.get(i);
        if (ln.trim().length() == 0 || ln.startsWith("#")) continue;
        @PKG@.LgSite s = @PKG@.LgSite.parse(ln);
        if (s == null) bad++; else l.add(s);
      }
    }
  } catch (Throwable t) {
    @PKG@.ExpCfg.warnEvery("lgread|" + wf, 60000L, "could not read " + f + " (" + t + ") - the luggage of world " + wn + " pauses (nothing placed, claimed or removed) until it reads; the file is never overwritten");
    return null;
  }
  if (bad > 0) {
    java.nio.file.Path bk = DIR.resolve(wf + "-" + System.currentTimeMillis() + ".tsv.bad");
    try { java.nio.file.Files.copy(f, bk, new java.nio.file.CopyOption[0]); }
    catch (Throwable t) {
      @PKG@.ExpCfg.warnEvery("lgread|" + wf, 60000L, "could not back up " + f + " (" + t + ") - the luggage of world " + wn + " pauses until it can; the file is never overwritten");
      return null;
    }
    @PKG@.ExpCfg.warn("skipped " + bad + " unreadable line(s) in " + f + " - the whole file was copied to " + bk.getFileName() + " first");
  }
  Object prev = W.putIfAbsent(wf, l);
  NAMES.put(wf, wn);
  return prev instanceof java.util.ArrayList ? (java.util.ArrayList) prev : l;
}""")
M(lgreg, r"""
public static boolean save(String wn) {
  String wf = @PKG@.ChestReg.wf(wn);
  java.util.ArrayList l = (java.util.ArrayList) W.get(wf);
  if (l == null || DIR == null) return false;      // never write a world whose file was not read
  StringBuilder sb = new StringBuilder("# SkyyExploration Unclaimed Luggage - world " + wn + ": x y z tier level state(0 out, 1 claimed, 2 gone) placedAt lootedAt lastNear nonce claims\n");
  Object[] arr = snap(l);
  for (int i = 0; i < arr.length; i++) sb.append(((@PKG@.LgSite) arr[i]).line()).append('\n');
  try {
    java.nio.file.Files.createDirectories(DIR, new java.nio.file.attribute.FileAttribute[0]);
    java.nio.file.Path f = file(wf);
    java.nio.file.Path tmp = DIR.resolve(wf + ".tsv.tmp");
    java.nio.file.Files.write(tmp, sb.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8), new java.nio.file.OpenOption[0]);
    @PKG@.ExpIO.moveRetry(tmp, f);
    return true;
  } catch (Throwable t) {
    SAVE_FAILS.incrementAndGet();
    @PKG@.ExpCfg.warnEvery("lgsave", 60000L, "could not save the luggage of world " + wn + ": " + t + " - nothing is placed or given until it saves");
    return false;
  }
}""")
# a world that has (or had) luggage: loaded, or its file exists (the off / excluded cleanup never creates a file)
M(lgreg, r"""
public static boolean known(String wn) {
  String wf = @PKG@.ChestReg.wf(wn);
  if (W.containsKey(wf)) return true;
  java.nio.file.Path f = file(wf);
  try { return f != null && java.nio.file.Files.exists(f, new java.nio.file.LinkOption[0]); } catch (Throwable t) { return false; }
}""")
M(lgreg, r"""
public static @PKG@.LgSite at(java.util.ArrayList l, int x, int y, int z) {
  if (l == null) return null;
  Object[] arr = snap(l);
  for (int i = 0; i < arr.length; i++) {
    @PKG@.LgSite s = (@PKG@.LgSite) arr[i];
    if (s.x == x && s.y == y && s.z == z) return s;
  }
  return null;
}""")
M(lgreg, r"""
public static int count(java.util.ArrayList l, int state) {
  int n = 0;
  if (l == null) return 0;
  Object[] arr = snap(l);
  for (int i = 0; i < arr.length; i++) if (((@PKG@.LgSite) arr[i]).state == state) n++;
  return n;
}""")

