# once a second per world: claimed luggage vanishes after the share time, unvisited luggage goes away, lines whose block is gone are
# dropped, long-gone sites are forgotten (only loaded chunks are touched - an unloaded site waits)
M(lgcore, r"""
public static int sweep(@WLD@ w, String wn, java.util.ArrayList sites, long now) {
  Object last = SWEPT.get(wn);
  if (last instanceof Long && now - ((Long) last).longValue() < 1000L && now >= ((Long) last).longValue()) return 0;
  SWEPT.put(wn, Long.valueOf(now));
  int changed = 0;
  long share = @PKG@.ExpCfg.LG_SHARE_S * 1000L, desp = @PKG@.ExpCfg.LG_DESPAWN_S * 1000L, resp = @PKG@.ExpCfg.LG_RESPAWN_S * 1000L;
  Object[] arr;
  arr = @PKG@.LgReg.snap(sites);
  for (int i = 0; i < arr.length; i++) {
    @PKG@.LgSite s = (@PKG@.LgSite) arr[i];
    if (s.state == 1 && now - s.lootedAt >= share) {
      if (unplace(w, s)) { s.state = 2; changed++; count(2, 1L); }
      continue;
    }
    if (s.state == 0) {
      String id = @PKG@.LgEng.blockId(w, s.x, s.y, s.z);
      if (id == null) continue;
      if (!ours(id)) { @PKG@.LgReg.remove(sites, s); changed++; count(11, 1L); continue; }
      long seen = s.lastNear > 0L ? s.lastNear : s.placedAt;
      if (now - seen >= desp) {
        if (unplace(w, s)) { @PKG@.LgReg.remove(sites, s); changed++; count(4, 1L); }
      }
      continue;
    }
    if (s.state == 2 && now - s.lootedAt > resp + 6L * 3600000L) { @PKG@.LgReg.remove(sites, s); changed++; count(11, 1L); }
  }
  if (changed > 0) @PKG@.LgReg.save(wn);
  return changed;
}""")
# luggage switched off, or the world is excluded now: every luggage of that world in a loaded chunk goes (only our blocks with a line),
# waiting sites are forgotten - nothing is stranded (unclaimable and unbreakable) in the world. Once a second per world.
M(lgcore, r"""
public static int offSweep(@WLD@ w, String wn, long now) {
  Object last = SWEPT.get(wn);
  if (last instanceof Long && now - ((Long) last).longValue() < 1000L && now >= ((Long) last).longValue()) return 0;
  SWEPT.put(wn, Long.valueOf(now));
  if (!@PKG@.LgReg.known(wn)) return 0;
  java.util.ArrayList sites = @PKG@.LgReg.sites(wn);
  if (sites == null) return 0;
  int changed = 0;
  Object[] arr = @PKG@.LgReg.snap(sites);
  for (int i = 0; i < arr.length; i++) {
    @PKG@.LgSite s = (@PKG@.LgSite) arr[i];
    if (s.state == 2) { @PKG@.LgReg.remove(sites, s); changed++; count(11, 1L); continue; }
    if (unplace(w, s)) { @PKG@.LgReg.remove(sites, s); changed++; count(4, 1L); }
  }
  if (changed > 0) @PKG@.LgReg.save(wn);
  return changed;
}""")
# gone sites near a player come back full at the same spot (when it is still a valid spot), else they are forgotten
M(lgcore, r"""
public static int respawn(@WLD@ w, String wn, java.util.ArrayList sites, double px, double pz, long now) {
  long resp = @PKG@.ExpCfg.LG_RESPAWN_S * 1000L;
  Object[] arr;
  arr = @PKG@.LgReg.snap(sites);
  int n = 0;
  for (int i = 0; i < arr.length; i++) {
    @PKG@.LgSite s = (@PKG@.LgSite) arr[i];
    if (s.state != 2 || now - s.lootedAt < resp || d2((double) s.x, (double) s.z, px, pz) > 64.0 * 64.0) continue;
    if (@PKG@.LgEng.blockId(w, s.x, s.y, s.z) == null) continue;
    if (@PKG@.LgEng.occupied(w, s.x, s.y, s.z)) continue;      // someone stands on the spot: try again next second
    int y = column(w, sites, s.x, s.z, s);
    if (y != s.y) { @PKG@.LgReg.remove(sites, s); @PKG@.LgReg.save(wn); count(11, 1L); continue; }
    long oP = s.placedAt, oN = s.lastNear, oL = s.lootedAt, oX = s.nonce;
    s.state = 0; s.placedAt = now; s.lastNear = now; s.lootedAt = 0L; s.nonce = RNG.nextLong();
    if (!@PKG@.LgReg.save(wn)) { s.state = 2; s.placedAt = oP; s.lastNear = oN; s.lootedAt = oL; s.nonce = oX; continue; }   // unsaved: nothing changes
    boolean ok = false;
    try { ok = @PKG@.LgEng.place(w, s.x, s.y, s.z, IDS[s.tier - 1]); } catch (Throwable t) { ok = false; }
    if (!ok) { @PKG@.LgReg.remove(sites, s); @PKG@.LgReg.save(wn); continue; }
    count(3, 1L);
    try { @PKG@.LgEng.sound(w, s.x, s.y, s.z); } catch (Throwable t) { }
    n++;
  }
  return n;
}""")
# try up to 8 random columns in the ring around the player; the level is SkyyMobs' level at the spot (none = no luggage there)
M(lgcore, r"""
public static @PKG@.LgSite spawnNear(@WLD@ w, String wn, java.util.ArrayList sites, double px, double pz, long now) {
  int nearP = 0, area = 0, total = 0;
  Object[] arr = @PKG@.LgReg.snap(sites);
  for (int i = 0; i < arr.length; i++) {
    @PKG@.LgSite s = (@PKG@.LgSite) arr[i];
    if (s.state == 2) continue;
    total++;
    if (d2((double) s.x, (double) s.z, px, pz) <= 64.0 * 64.0) nearP++;
    if (Math.abs((double) s.x - px) <= 64.0 && Math.abs((double) s.z - pz) <= 64.0) area++;
  }
  if ((long) nearP >= @PKG@.ExpCfg.LG_PER_PLAYER || (long) area >= @PKG@.ExpCfg.LG_PER_AREA || (long) total >= @PKG@.ExpCfg.LG_WORLD_MAX) return null;
  double rmin = (double) @PKG@.ExpCfg.LG_RING_MIN, rmax = (double) @PKG@.ExpCfg.LG_RING_MAX;
  for (int k = 0; k < 8; k++) {
    double a = RNG.nextDouble() * Math.PI * 2.0;
    double d = rmin + RNG.nextDouble() * (rmax - rmin);
    int x = (int) Math.floor(px + Math.cos(a) * d);
    int z = (int) Math.floor(pz + Math.sin(a) * d);
    int y = column(w, sites, x, z, null);
    if (y < 0) continue;
    Object[] lv = @PKG@.LgEng.levelAt(wn, x, y, z);
    if (lv == null || lv.length < 2 || !(lv[0] instanceof Integer) || !(lv[1] instanceof Integer)) { count(12, 1L); return null; }
    int lo = ((Integer) lv[0]).intValue(), hi = ((Integer) lv[1]).intValue();
    if (lo < 1) return null;
    if (hi < lo) hi = lo;
    int L = lo + RNG.nextInt(hi - lo + 1);
    return spawn(w, wn, sites, x, y, z, pickTier(zoneOf(L)), L, now);
  }
  count(9, 1L);
  return null;
}""")
# ExpTick.second (once a second per player, the player's world thread)
M(lgcore, r"""
public static void second(@PR@ pr, @PLA@ p, @REF@ ref, @ST@ store, java.util.UUID u, @PKG@.ExpState st, @WLD@ w, boolean creative, boolean flying, long now) {
  if (w == null || st == null) return;
  String wn = w.getName();
  if (!@PKG@.ExpCfg.LG_ON || @PKG@.ExpCfg.excluded(wn)) { offSweep(w, wn, now); return; }
  @TRC@ tc = (@TRC@) store.getComponent(ref, @TRC@.getComponentType());
  if (tc == null || tc.getPosition() == null) return;
  double px = tc.getPosition().x, pz = tc.getPosition().z;
  if (!st.lgHas || d2(st.lgX, st.lgZ, px, pz) >= 32.0 * 32.0) { st.lgX = px; st.lgZ = pz; st.lgMoved = now; st.lgHas = true; }
  java.util.ArrayList sites = @PKG@.LgReg.sites(wn);
  if (sites == null) return;
  sweep(w, wn, sites, now);
  Object[] arr = @PKG@.LgReg.snap(sites);
  for (int i = 0; i < arr.length; i++) {
    @PKG@.LgSite s = (@PKG@.LgSite) arr[i];
    if (s.state == 0 && d2((double) s.x, (double) s.z, px, pz) <= 96.0 * 96.0) s.lastNear = now;
  }
  respawn(w, wn, sites, px, pz, now);
  st.lgAcc = st.lgAcc + 1L;
  if (st.lgAcc < @PKG@.ExpCfg.LG_SPAWN_S) return;
  st.lgAcc = 0L;
  if (creative || flying || @PKG@.ExpIO.busy(u) || now - st.lgMoved > @PKG@.ExpCfg.LG_AFK_S * 1000L) return;
  spawnNear(w, wn, sites, px, pz, now);
}""")
