# the loot of one claim (the registry already says this player claimed it - written before this runs)
M(lgcore, r"""
public static String loot(@CAC@ acc, @REF@ ref, @PR@ pr, @PLA@ p, java.util.UUID u, @PKG@.LgSite s) {
  int tier = s.tier < 1 ? 1 : (s.tier > 4 ? 4 : s.tier);
  int L = s.lvl;
  int zone = zoneOf(L);
  StringBuilder sb = new StringBuilder();
  double cmin = @PKG@.ExpCfg.LG_COIN_MIN[tier - 1], cmax = @PKG@.ExpCfg.LG_COIN_MAX[tier - 1];
  if (cmax < cmin) cmax = cmin;
  long coins = Math.round((cmin + RNG.nextDouble() * (cmax - cmin)) * @PKG@.ExpCfg.LG_COIN_ZM[zone - 1]);
  if (coins > 0L && @PKG@.ExpSkill.coins(u, coins)) { sb.append("+").append(@PKG@.ExpDefs.grp(coins)).append(" coins"); count(6, coins); }
  double bavg = @PKG@.ExpCfg.LG_BAGS[tier - 1];
  int nb = (int) Math.floor(bavg) + (RNG.nextDouble() < bavg - Math.floor(bavg) ? 1 : 0);
  java.util.function.Function bx = @PKG@.ExpIO.fn("gear:fn:box");
  for (int k = 0; k < nb && bx != null; k++) {
    Object b = null;
    try { b = bx.apply(new Object[] { null, Integer.valueOf(L), "lootchest", Integer.valueOf(tier), u }); } catch (Throwable t) { b = null; }
    if (!(b instanceof @IS@)) continue;
    give(acc, ref, p, (@IS@) b);
    if (sb.length() > 0) sb.append(", ");
    sb.append(bagName((@IS@) b));
    count(5, 1L);
  }
  if (@PKG@.ExpCfg.LG_VANILLA) {
    java.util.List drops = null;
    try { drops = @IMOD@.get().getRandomItemDrops("Zone" + zone + "_Encounters_Tier" + tier); } catch (Throwable t) { drops = null; }
    for (int i = 0; drops != null && i < drops.size(); i++) {
      Object o = drops.get(i);
      if (!(o instanceof @IS@)) continue;
      @IS@ is = (@IS@) o;
      if (is.isEmpty() || is.getItemId() == null) continue;
      String id = is.getItemId();
      if (id.startsWith("Weapon_") || id.startsWith("Armor_")) is = asBag(is, L, tier, u);
      give(acc, ref, p, is);
      if (sb.length() > 0) sb.append(", ");
      sb.append(is.getQuantity() > 1 ? is.getQuantity() + " " : "").append(@PKG@.ExpCfg.LG_ON ? bagName(is) : id);
    }
  }
  long xp = Math.round(@PKG@.ExpCfg.LG_XP[tier - 1] * @PKG@.ExpCfg.CHEST_ZM[zone - 1]);
  String k = @PKG@.ExpIO.pkey(u);
  @PKG@.ExpData d = @PKG@.ExpStore.dataK(k, u);
  if (xp > 0L && d != null && !d.bad) {
    @PKG@.ExpStore.addOwed(d, xp);
    @PKG@.ExpStore.saveSoon(k);
    @PKG@.ExpXp.flush(u, k, d);
    if (sb.length() > 0) sb.append(", ");
    sb.append("+").append(@PKG@.ExpDefs.grp(xp)).append(" Exploration XP");
  }
  return sb.toString();
}""")
# Use on a luggage block (OpenCustomUI supplier, the player's world thread): checks, the claim WRITTEN FIRST, then the loot
M(lgcore, r"""
public static int use(@REF@ ref, @CAC@ acc, @PR@ pr, int x, int y, int z) {
  if (pr == null || ref == null || acc == null) return -1;
  Object ext = acc.getExternalData();
  if (!(ext instanceof @EST@)) return -1;
  @WLD@ w = ((@EST@) ext).getWorld();
  if (w == null) return -1;
  String wn = w.getName();
  String id = @PKG@.LgEng.blockId(w, x, y, z);
  if (!ours(id)) return -1;
  java.util.UUID u = pr.getUuid();
  long now = System.currentTimeMillis();
  String col = "#ffd27a";
  if (!@PKG@.ExpCfg.LG_ON) { say(pr, "[Exploration] Unclaimed Luggage is switched off on this server.", col); return 0; }
  @PLA@ p = (@PLA@) acc.getComponent(ref, @PLA@.getComponentType());
  if (p == null) return -1;
  if (@PKG@.ExpAward.creative(p)) { say(pr, "[Exploration] Luggage cannot be claimed in creative mode.", col); return 0; }
  if (@PKG@.ExpIO.busy(u) || @PKG@.ExpIO.switchWait(u) > 0L) { say(pr, "[Exploration] Your profile is switching - try again in a moment.", col); return 0; }
  java.util.ArrayList sites = @PKG@.LgReg.sites(wn);
  if (sites == null) { say(pr, "[Exploration] This luggage cannot be opened right now - try again later.", col); return 0; }
  @PKG@.LgSite s = @PKG@.LgReg.at(sites, x, y, z);
  if (s == null || s.state == 2) { say(pr, "[Exploration] This luggage is empty.", col); return 0; }
  if (s.state == 1 && now - s.lootedAt >= @PKG@.ExpCfg.LG_SHARE_S * 1000L) { say(pr, "[Exploration] This luggage is already vanishing.", col); return 0; }
  long last = s.claimedAt(u);
  if (last > 0L && last >= s.placedAt) {
    count(8, 1L);
    say(pr, "[Exploration] You already claimed this luggage.", col);
    return 0;
  }
  if (last > 0L && now - last < @PKG@.ExpCfg.LG_SITE_CD * 1000L && now >= last) {
    count(8, 1L);
    long mins = (@PKG@.ExpCfg.LG_SITE_CD * 1000L - (now - last) + 59999L) / 60000L;
    say(pr, "[Exploration] You looted this spot recently - you can claim it again in " + mins + " min.", col);
    return 0;
  }
  if (!capOk(u, now)) {
    count(7, 1L);
    say(pr, "[Exploration] You claimed " + @PKG@.ExpCfg.LG_CAP + " luggage in the last hour - more later.", col);
    return 0;
  }
  String oldWho = s.who;
  int oldState = s.state;
  long oldAt = s.lootedAt;
  s.claim(u, now, @PKG@.ExpCfg.LG_SITE_CD * 1000L);
  if (s.state == 0) { s.state = 1; s.lootedAt = now; }
  if (!@PKG@.LgReg.save(wn)) {
    s.who = oldWho; s.state = oldState; s.lootedAt = oldAt;
    say(pr, "[Exploration] The luggage could not be saved - nothing was taken. Try again.", col);
    return 0;
  }
  capAdd(u, now);
  count(1, 1L);
  String got = "";
  try { got = loot(acc, ref, pr, p, u, s); } catch (Throwable t) { @PKG@.ExpCfg.warnEvery("lgloot", 60000L, "luggage loot failed (the claim is saved): " + t); }
  if (@PKG@.ExpIO.notifyOn(u, "explore.finds")) say(pr, "[Exploration] Unclaimed Luggage (" + TIER[s.tier] + ", Lv " + s.lvl + "): " + (got.length() > 0 ? got : "it was empty"), col);
  return 1;
}""")
