def jA(parent, mk):
    """b.appendInline(<#parent>, <kit markup>): parent = a static id or JX("par", "SkyyExTL") (a Java String holding the id, no #). The
    kit runs check_markup on the markup (both looks of a choose()) before it emits the statement."""
    return SUI.java_append(parent, mk)


def jS(ident, expr, guard=True):
    """b.set("#ident.Text", <Java expression>); guard=True keeps 0.2.1's null guard (text == null ? "" : text) through nz()."""
    return SUI.java_set(ident, "Text", JX(("nz(" + expr + ")") if guard else expr, "x"))


def jL(parent, ident, expr, kind, guard=True, **kw):
    """A kit label with an empty inline text + its b.set line (0.2.1's line() / lab() helpers sent every label text through b.set), as one
    Java block { ... } - safe after an if / else."""
    return "{ " + jA(parent, SUI.label(ident, "", kind, **kw)) + " " + jS(ident, expr, guard) + " }"


def jEv(ident, data):
    """0.2.1's Activating binding on #ident with its EventData (a Java expression)."""
    return "ev.addEventBinding(@BT@.Activating, %s, %s);" % (SUI.java_value("#" + ident), data)


def jB(parent, ident, text, data, kind="secondary", **kw):
    """A kit button (the 0.2.1 label, inline) + its binding, in 0.2.1's order (append, then bind)."""
    return "{ " + jA(parent, SUI.button(ident, text, kind, **kw)) + " " + jEv(ident, data) + " }"


def jTab(parent, ident, text, cond, data, w, anchor=None):
    """One tab of the vanilla tab row (EntitySpawnPage: the active tab Primary, the others Secondary; fixed width, no FlexWeight),
    the look picked at runtime (choose) + its binding."""
    return "{ " + jA(parent, SUI.choose(JX(cond), SUI.button(ident, text, "primary", w=w, anchor=anchor),
                                        SUI.button(ident, text, "secondary", w=w, anchor=anchor))) + " " + jEv(ident, data) + " }"


def jSep(parent):
    """The vanilla content separator (1 px #2b3542, 8 px above and below - WorldEventPanelPage)."""
    return jA(parent, SUI.separator("content", anchor={"top": SUI.SEP_MARGIN, "bottom": SUI.SEP_MARGIN}))


