def frow(ident):
    """An editor row (LayoutMode Left, 44 high, 8 below)."""
    return SUI.group(ident, "Left", h=XA_FROW_H, anchor={"bottom": XA_FROW_B})


def jF(parent, fid, w, maxlen, placeholder, value_expr, left=0, ph_expr=None):
    """A vanilla text field (the kit's InputBox box #<fid>Box + TextField #fid, as 0.2.1's box()) + 0.2.1's value keep (val()). A
    placeholder that 0.2.1 computed at runtime (ph_expr: the default radius / XP) is spliced into the kit markup (KIT-GAP: text_field
    takes a static placeholder only; the checked markup is the one with the sample, the runtime value passes 0.2.1's ph() filter
    [A-Za-z0-9 .-])."""
    anc = {"top": XA_FIELD_T}
    if left:
        anc["left"] = left
    mk = SUI.text_field(fid + "Box", fid, w=w, max_length=maxlen, placeholder=placeholder, anchor=anc)
    if ph_expr is None:
        app = jA(parent, mk)
    else:
        SUI.check_markup(mk)
        needle = 'PlaceholderText: "%s"; ' % placeholder
        assert mk.count(needle) == 1, mk
        mkj = mk.replace(needle, 'PlaceholderText: "' + JX("ph(" + ph_expr + ")", placeholder) + '"; ')
        app = "b.appendInline(%s, %s);" % (SUI.java_value("#" + parent), SUI.java_expr(mkj))
    return "{ " + app + " val(b, %s, %s); }" % (SUI.java_value("#" + fid), value_expr)


def jTog(parent, ident, text, data, on, w, left=0):
    """An ON / OFF toggle (0.2.1's gold ON / grey OFF pair): the Tertiary button, Tertiary_Active when on (the kit's quiet toggle)."""
    return jB(parent, ident, text, data, "tertiary", selected=on, w=w, anchor={"left": left} if left else None)


def jRow(prefix, sel_expr, name_expr, name_col, sub_expr, sub_col, edit_id, edit_data, word_id):
    """One list row (0.2.1's #SkyyXa[C]Row<i>, 66 high on the list well): the static row panel; the selected row (0.2.1: the lighter
    row) in the WorldEventListRow pressed step with the blue status bar (the kit's list_card "selected" look), the name (18 px bold, one
    line: clip() cuts a name wider than the text column and ends it in "...") + the two-line sub (15 px) - then Edit (small Secondary, 44 high, centred) or the
    word Editing (success green, where the button was). Returns the Java (appends, b.set lines, the binding in 0.2.1's place)."""
    rid, pid, tid = prefix + _i, prefix + "P" + _i, prefix + "T" + _i
    head = LF.join([
        jA("SkyyXaRows", SUI.group(rid, "Left", h=XA_ROW_H, anchor={"bottom": SUI.ROW_GAP})),
        "  " + jA(rid, SUI.panel(pid, "row", w=XA_ROW_PW, h=XA_ROW_H, layout="Left", pad={"left": 8, "right": 8},
                                 bg=SUI.color_by([(sel_expr, "rowPressed")], "row"))),
        "  " + jA(pid, SUI.status_bar(prefix + "B" + _i, on=JX(sel_expr))),
        "  " + jA(pid, SUI.group(tid, "Top", w=XA_ROW_TW, h=XA_ROW_H)),
        "  " + jL(tid, prefix + "N" + _i, "clip(" + name_expr + ")", "rowName", h=XA_NAME_H, col=name_col),
        "  " + jL(tid, prefix + "S" + _i, sub_expr, "rowSub", h=XA_RSUB_H, wrap=True, valign=False, col=sub_col)])
    word = jL(rid, word_id + _i, '"Editing"', "bold", w=XA_ACT_W, h=XA_ROW_H, align="Center", col="success", anchor={"left": 4})
    edit = LF.join([jA(rid, SUI.group(prefix + "A" + _i, "Left", w=4 + XA_ACT_W, h=XA_ROW_H, pad={"left": 4, "top": XA_ACT_TOP})),
                    "      " + jB(prefix + "A" + _i, edit_id + _i, "Edit", edit_data, "secondary", size="small", w=XA_ACT_W, h=SUI.BTN_H)])
    return head + LF + "    if (" + sel_expr + ") " + word + LF + "    else {" + LF + "      " + edit + LF + "    }"


