# one string value out of the page event JSON (SkyySacks 0.7.3 CraftPage.jsonStr / SkyyGuilds 0.1.1, verified in game)
M(apg, r"""
public static String jsonStr(String data, String key) {
  if (data == null || key == null) return "";
  String qt = String.valueOf((char) 34);
  int i = data.indexOf(qt + key + qt);
  if (i < 0) return "";
  i = data.indexOf(':', i + key.length() + 2);
  if (i < 0) return "";
  i++;
  while (i < data.length() && Character.isWhitespace(data.charAt(i))) i++;
  if (i >= data.length() || data.charAt(i) != 34) return "";
  i++;
  StringBuilder sb = new StringBuilder();
  while (i < data.length() && sb.length() < 200) {
    char c = data.charAt(i);
    if (c == 34) break;
    if (c == 92 && i + 1 < data.length()) {
      char n = data.charAt(i + 1);
      if (n == 'u' && i + 5 < data.length()) {
        try { sb.append((char) Integer.parseInt(data.substring(i + 2, i + 6), 16)); } catch (Throwable t) { }
        i += 6;
        continue;
      }
      if (n == 'n' || n == 'r' || n == 't' || n == 'b' || n == 'f') sb.append(' '); else sb.append(n);
      i += 2;
      continue;
    }
    sb.append(c);
    i++;
  }
  return sb.toString();
}""")
# placeholders are plain words / digits only (they sit in the markup)
M(apg, r"""
public static String ph(String s) {
  if (s == null) return "";
  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < s.length() && sb.length() < 30; i++) {
    char c = s.charAt(i);
    if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == ' ' || c == '-' || c == '.') sb.append(c);
  }
  return sb.toString();
}""")
M(apg, r"""
public static String nz(String s) {
  return s == null ? "" : s;
}""")
# 0.2.2 review fix: a list row name is ONE line (18 px bold). The vanilla row name truncates itself (Wrap + WrapMaxLines: 1), but
# WrapMaxLines stays off until the base probe passes - so a name wider than the row's text column (XA_ROW_TW) is cut here to the widest
# prefix that fits with "..." (a custom checklist task is up to 80 letters; the editor field on the right shows the whole text). Widths
# = the kit's text_width (the client's own glyph advances, in 1/100 px, rounded up); a character outside 32..126 counts as wide as M.
# A name that fits comes back unchanged (0.2.1's b.set text).
_RN_SIZE, _RN_BOLD = SUI.fs(SUI.LABELS["rowName"][0]), bool(SUI.LABELS["rowName"][2])
def _rn_w(t):
    import math
    return int(math.ceil(SUI.text_width(t, _RN_SIZE, _RN_BOLD) * 100))


_RN_CW, _RN_WM, _RN_DOTS, _RN_MAX = [_rn_w(chr(c)) for c in range(32, 127)], _rn_w("M"), _rn_w("..."), XA_ROW_TW * 100
assert _RN_SIZE == 18 and _RN_BOLD and min(_RN_CW) > 0 and _RN_MAX == 43000, (_RN_SIZE, _RN_BOLD, _RN_MAX)
M(apg, r"""
public static String clip(String s) {
  if (s == null) return "";
  int[] cw = """ + jint(_RN_CW) + r""";
  int tot = 0;
  for (int i = 0; i < s.length(); i++) {
    char c = s.charAt(i);
    tot += (c >= ' ' && c <= '~') ? cw[c - 32] : """ + str(_RN_WM) + r""";
  }
  if (tot <= """ + str(_RN_MAX) + r""") return s;
  int acc = 0;
  int n = 0;
  while (n < s.length()) {
    char c = s.charAt(n);
    int w = (c >= ' ' && c <= '~') ? cw[c - 32] : """ + str(_RN_WM) + r""";
    if (acc + w + """ + str(_RN_DOTS) + r""" > """ + str(_RN_MAX) + r""") break;
    acc += w;
    n++;
  }
  if (n > 0 && Character.isHighSurrogate(s.charAt(n - 1))) n--;
  return s.substring(0, n).trim() + "...";
}""")
