with zipfile.ZipFile(ASSETS) as _z:
    _NAMES = set(_z.namelist())
    _SRCJ = {}
    for _src in ("Furniture_Crude_Chest_Small", "Furniture_Village_Chest_Small", "Furniture_Ancient_Chest_Small", "Furniture_Dungeon_Chest_Epic"):
        _p = [n_ for n_ in _NAMES if n_.startswith("Server/Item/Items/") and n_.endswith("/" + _src + ".json")]
        assert len(_p) == 1, _src
        _SRCJ[_src] = json.loads(_z.read(_p[0]).decode("utf-8-sig"))
LG_SRC = ["Furniture_Crude_Chest_Small", "Furniture_Village_Chest_Small", "Furniture_Ancient_Chest_Small", "Furniture_Dungeon_Chest_Epic"]
LG_NUM = ["I", "II", "III", "IV"]
LG_FILES = {}
_lang = []
for _i, (_bid, _src) in enumerate(zip(LG_IDS, LG_SRC)):
    _v = _SRCJ[_src]
    _vb = _v["BlockType"]
    for _k in ("CustomModel",):
        assert ("Common/" + _vb[_k]) in _NAMES, _vb[_k]
    for _t in _vb["CustomModelTexture"]:
        assert ("Common/" + _t["Texture"]) in _NAMES, _t
    assert ("Common/" + _v["Icon"]) in _NAMES, _v["Icon"]
    _bt = {"Material": "Solid", "DrawType": "Model", "Opacity": "Transparent", "CustomModel": _vb["CustomModel"],
           "CustomModelTexture": [{"Texture": _vb["CustomModelTexture"][0]["Texture"], "Weight": 1}],
           "HitboxType": _vb.get("HitboxType", "Chest_Small"), "VariantRotation": "NESW",
           "Gathering": {"Breaking": {"GatherType": "Woods", "DropList": "Empty"}},
           "BlockParticleSetId": "Wood", "BlockSoundSetId": "Wood", "PhysicalMaterialId": "Wood",
           "Support": {"Down": [{"FaceType": "Full"}]},
           "InteractionHint": "server.interactionHints.open",
           "Interactions": {"Use": {"Interactions": [{"Type": "OpenCustomUI", "Page": {"Id": LG_PAGE}}]}}}
    for _k in ("ParticleColor", "TextureComputedColor"):
        if _k in _vb:
            _bt[_k] = _vb[_k]
    LG_FILES["Server/Item/Items/SkyyExploration/%s.json" % _bid] = json.dumps({
        "TranslationProperties": {"Name": "server.items.%s.name" % _bid, "Description": "server.items.%s.description" % _bid},
        "Variant": True, "MaxStack": 1, "Icon": _v["Icon"], "IconProperties": _v.get("IconProperties", {"Scale": 0.55, "Translation": [0, -15], "Rotation": [22.5, 45, 22.5]}),
        "PlayerAnimationsId": "Block", "BlockType": _bt}, indent=2)
    assert _bid not in ITEM_IDS, _bid
    _lang.append("items.%s.name = Unclaimed Luggage (%s)" % (_bid, LG_NUM[_i]))
    _lang.append("items.%s.description = Lost luggage of the Department of Arrivals. Press F to claim what is inside - it vanishes soon after." % _bid)
assert "Server/Drops/Empty.json" in _NAMES or any(n_.startswith("Server/Drops/") and n_.endswith("/Empty.json") for n_ in _NAMES), "the vanilla Empty drop list is gone"
assert "Server/Item/Hitboxes/Chest_Small.json" in _NAMES or True
LG_FILES["Server/Languages/en-US/server.lang"] = "\n".join(_lang) + "\n"
for _k in LG_FILES:
    assert _k == "Server/Languages/en-US/server.lang" or _k not in _NAMES, "a luggage file would shadow a vanilla file: " + _k
print("0.2.4 Unclaimed Luggage: %d blocks (%s), page id %s, %d Server Setup rows" % (len(LG_IDS), ", ".join(LG_SRC), LG_PAGE,
      sum(1 for r in CFG_ROWS if r[2] == "luggage" or r[0] == "luggage.enabled")))
jar = os.path.join(HERE, "SkyyExploration-%s.jar" % VERSION)
m = B.manifest("SkyyExploration", VERSION, "SkyWynn Exploration: Exploration XP (SkyySkills 0.4.1) for the first open of every world loot chest (plus chest luck - an extra roll), every new chunk you walk into (never while flying or in creative), each of Hytale's zones and admin-placed discovery and secret spots (banner + sound on the first visit) - once per profile, no XP boosters. Unclaimed Luggage: Wynncraft-style loot chests appear on the surface near players (coins, SkyyGear mystery bags, a vanilla roll, XP), each player claims once, then they vanish and come back later; player chests are never touched. Island checklists with a % per profile and an optional 100% reward. Everything is set up in game: SkyWynn Menu -> Server Setup -> Exploration (every setting, with change log and undo), /exploreadmin (admin page: spots, checklist, island) and /exploreadmin set <key> <value> - the files always match. Titles show in front of your chat messages. /explore, /title. Per profile with SkyyProfiles (optional); reads SkyySkills / SkyyTrees / SkyyCoins through the skyy bridge; zero dependencies.", PKG + ".SkyyExplorationPlugin")
m["IncludesAssetPack"] = True       # 0.2.4: the four Unclaimed Luggage blocks + their names (the pages stay inline)
B.assemble(jar, m, OUT, LG_FILES)
if "--deploy" in sys.argv:   # only with Skyy's deploy OK (HANDOFF section 3); workflows never pass it
    B.deploy(jar, "SkyyExploration.jar")
    B.enable_in_world("HUD mod", "Skyy:%s SkyyExploration" % VERSION, disable_prefix="Skyy:")
